const { splitMarkdownIntoChunks } = (function(){
function isFence(line) {
  return /^\s*```/.test(line);
}

function headingLevel(line) {
  const m = /^(#{1,6})\s+\S/.exec(line);
  return m ? m[1].length : 0;
}

function isTableRow(line) {
  return /^\s*\|.*\|\s*$/.test(line);
}

function splitMarkdownIntoChunks(markdown, maxChars) {
  const max = Math.max(200, Number(maxChars) || 1500);
  const lines = String(markdown || "").replace(/\r\n/g, "\n").split("\n");
  const sections = [];
  let path = [];
  let buf = [];
  let startLine = 1;
  let inFence = false;

  function pathForLevel(level, title) {
    const next = path.filter((p) => p.level < level);
    next.push({ level, title });
    return next;
  }

  function flush() {
    const text = buf.join("\n").trim();
    if (!text) {
      buf = [];
      return;
    }
    sections.push({
      heading_path: path.map((p) => p.title),
      start_line: startLine,
      end_line: startLine + buf.length - 1,
      text,
    });
    buf = [];
  }

  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];
    if (isFence(line)) inFence = !inFence;
    const level = !inFence ? headingLevel(line) : 0;
    if (level) {
      flush();
      const title = line.replace(/^#{1,6}\s+/, "").trim();
      path = pathForLevel(level, title);
      startLine = i + 1;
      buf.push(line);
    } else {
      if (buf.length === 0) startLine = i + 1;
      buf.push(line);
    }
  }
  flush();

  const chunks = [];
  function pushChunk(section, text, start, end, part, of) {
    const chars = text.length;
    chunks.push({
      id: (section.heading_path.join(" > ") || "intro") + "#" + start,
      heading_path: section.heading_path,
      start_line: start,
      end_line: end,
      part,
      of,
      chars,
      approx_tokens: Math.round(chars / 4),
      text,
    });
  }

  for (const section of sections) {
    if (section.text.length <= max) {
      pushChunk(section, section.text, section.start_line, section.end_line, 1, 1);
      continue;
    }
    // Split on blank lines, but keep fenced blocks and tables together when they fit.
    const parts = [];
    const slines = section.text.split("\n");
    let acc = [];
    let fence = false;
    let table = [];
    function emitAcc() {
      const t = acc.join("\n").trim();
      if (t) parts.push(t);
      acc = [];
    }
    for (const line of slines) {
      if (isFence(line)) fence = !fence;
      if (!fence && isTableRow(line)) {
        table.push(line);
        continue;
      }
      if (table.length) {
        acc.push(table.join("\n"));
        table = [];
      }
      acc.push(line);
      if (!fence && line.trim() === "") emitAcc();
    }
    if (table.length) acc.push(table.join("\n"));
    emitAcc();

    let current = "";
    const packed = [];
    for (const p of parts) {
      if (!current) {
        current = p;
        continue;
      }
      if ((current + "\n\n" + p).length <= max) current = current + "\n\n" + p;
      else {
        packed.push(current);
        current = p;
      }
    }
    if (current) packed.push(current);
    packed.forEach((text, i) => {
      pushChunk(section, text, section.start_line, section.end_line, i + 1, packed.length);
    });
  }
  return chunks;
}
return { splitMarkdownIntoChunks };
})();

const cfg = $input.first().json;
const markdown = cfg.SAMPLE_MARKDOWN || cfg.markdown || "";
const maxChars = cfg.MAX_CHARS || 1500;
if (!String(markdown).trim()) {
  throw new Error("Paste Markdown into SAMPLE_MARKDOWN in the configuration node.");
}
const chunks = splitMarkdownIntoChunks(markdown, maxChars);
if (!chunks.length) {
  throw new Error("No chunks were created. Check that the Markdown is not empty.");
}
return chunks.map((chunk) => ({ json: chunk }));

const items = $input.all();
const text = items.map((i) => JSON.stringify(i.json)).join("\n");
return [
  {
    json: { rows: items.length, fileName: "chunks.jsonl" },
    binary: {
      data: {
        data: Buffer.from(text, "utf8").toString("base64"),
        mimeType: "application/x-ndjson",
        fileName: "chunks.jsonl",
        fileExtension: "jsonl",
      },
    },
  },
];
